            const vars = active?.vars || DEFAULT_VARS;
            const isReadonly = active?.readonly || false;

            const cInput = (label, key, imgKey) => {
                let imgHtml = '';
                if (imgKey) {
                    const hasImg = !!vars[imgKey];
                    imgHtml = `<button class="sb-img-btn ${hasImg ? 'active' : ''}" data-img="${imgKey}" title="上传本地图片" ${isReadonly?'disabled':''}>🖼️</button>` +
                              (hasImg ? `<button class="sb-img-btn clear" data-clear="${imgKey}" title="清除图片" ${isReadonly?'disabled':''}>❌</button>` : '');
                }
                let pickerVal = '#ffffff';
                if (vars[key] && typeof vars[key] === 'string') {
                    if (vars[key].match(/^#[0-9A-Fa-f]{6}$/)) pickerVal = vars[key];
                    else if (vars[key].match(/^#[0-9A-Fa-f]{3}$/)) {
