                    <div class="sb-ctrl-slider">
                        <input type="range" class="sb-range-input" data-var="${key}" data-unit="${unit}" min="0" max="${max}" step="${step}" value="${vars[key] !== undefined ? vars[key] : 100}" ${isReadonly?'disabled':''}>
